 static String clean(String s){if(s==null)return "";s=s.replaceAll("[\p{Cntrl}\s]+"," ").trim();return s.length()>160?s.substring(0,160):s;}
 static String description(byte[] bytes){String title="",author="";try{ExifInterface exif=new ExifInterface(new ByteArrayInputStream(bytes));title=clean(exif.getAttribute("ImageDescription"));author=clean(exif.getAttribute("Artist"));if(title.toUpperCase(Locale.ROOT).contains("DIGITAL CAMERA"))title="";}catch(Exception ignored){}return (title.isEmpty()?"":title+"\n")+"Источник: Unsplash"+(author.isEmpty()?"":" · "+author);}
 static String reason(Exception e,String stage){if(e instanceof UnknownHostException)return "Не удалось найти сервер фотографий (DNS).";if(e instanceof SocketTimeoutException)return "Сервер фотографий не ответил вовремя.";if(e instanceof javax.net.ssl.SSLException)return "Не удалось установить защищённое соединение.";String message=e.getMessage();return stage+": "+(message==null?e.getClass().getSimpleName():clean(message));}
